using System;using System.Collections;using System.Collections.Generic;using System.IO;using System.Linq;using System.Reflection;using UnityEditor;using UnityEngine;using UnityEngine.SceneManagement;using UnityEngine.UI;using UnityEngine.InputSystem;using UnityEngine.InputSystem.LowLevel;using UnityEngine.Video;using Abyss;using Abyss.Story;
public static class VoyagePolishCheck {
 static Stack<IEnumerator> work;static string report;static double deadline;static int errors;static float originalMaster,originalMusic;
 public static void Begin(){Directory.CreateDirectory("Tools/PolishUpdate");report="Current requested polish - Play Mode checks\nRuntime-only controlled inputs and chapter-boundary setup; no combat tuning changed by tests.\n";errors=0;originalMaster=PlayerPrefs.GetFloat("Sound.Master",.85f);originalMusic=PlayerPrefs.GetFloat("Sound.Music",.7f);deadline=EditorApplication.timeSinceStartup+180;work=new();work.Push(Run());Application.logMessageReceived+=Log;EditorApplication.update+=Tick;EditorWindow.GetWindow(typeof(EditorWindow).Assembly.GetType("UnityEditor.GameView")).Focus();}
 static void Log(string message,string trace,LogType type){if(type==LogType.Error||type==LogType.Exception)errors++;}
 static void Tick(){Application.runInBackground=true;EditorApplication.QueuePlayerLoopUpdate();try{if(EditorApplication.timeSinceStartup>deadline)throw new Exception("Polish check timeout");if(work.Count==0){Finish();return;}var e=work.Peek();if(!e.MoveNext()){work.Pop();return;}if(e.Current is IEnumerator child)work.Push(child);else if(e.Current is AsyncOperation op)work.Push(Op(op));}catch(Exception e){report+="FAIL "+e+"\n";Finish();}}
 static void Finish(){File.WriteAllText("Tools/PolishUpdate/check.txt",report);PlayerPrefs.SetFloat("Sound.Master",originalMaster);PlayerPrefs.SetFloat("Sound.Music",originalMusic);AudioListener.volume=originalMaster;PlayerPrefs.Save();EditorApplication.update-=Tick;Application.logMessageReceived-=Log;}
 static IEnumerator Op(AsyncOperation op){while(!op.isDone)yield return null;}
 static IEnumerator Wait(float seconds){double t=EditorApplication.timeSinceStartup+seconds;while(EditorApplication.timeSinceStartup<t)yield return null;}
 static void Check(bool ok,string text){report+=(ok?"PASS ":"FAIL ")+text+"\n";File.WriteAllText("Tools/PolishUpdate/check.txt",report);if(!ok)throw new Exception(text);}
 static IEnumerator Talk(){double end=EditorApplication.timeSinceStartup+10;var d=UnityEngine.Object.FindFirstObjectByType<ShipVisitDialogue>();while(d&&!d.ReadyForGameplay&&EditorApplication.timeSinceStartup<end){if(d.UI.Active)d.UI.Advance();yield return null;}Check(d&&d.ReadyForGameplay,"Ship textbox returns control");}
 static void Stage(JourneyStage stage){typeof(StorySceneJourney).GetProperty("Stage").SetValue(StorySceneJourney.Instance,stage);typeof(StorySceneJourney).GetProperty("JourneyStarted").SetValue(StorySceneJourney.Instance,true);}
 static IEnumerator Run(){
  Check(!PlayerSettings.SplashScreen.show&&!PlayerSettings.SplashScreen.showUnityLogo&&PlayerSettings.companyName=="Andronova Games","Unity splash disabled; studio is Andronova Games");
  typeof(VoyageMainMenu).GetField("introPlayed",BindingFlags.NonPublic|BindingFlags.Static).SetValue(null,false);Time.timeScale=1;yield return SceneManager.LoadSceneAsync("MainMenu");yield return Wait(.3f);var menu=UnityEngine.Object.FindFirstObjectByType<VoyageMainMenu>();Check(!menu.GetComponentsInChildren<Button>(true).Any(b=>b.name=="Skip intro"),"Intro has no skip button");var video=UnityEngine.Object.FindFirstObjectByType<VideoPlayer>();double end=EditorApplication.timeSinceStartup+15;while(video&&!video.isPrepared&&EditorApplication.timeSinceStartup<end)yield return null;Check(video&&video.isPrepared,"Intro video prepared");video.time=Math.Max(0,video.length-.4);while(!menu.IntroHolding&&EditorApplication.timeSinceStartup<end)yield return null;Check(menu.IntroHolding,"Intro holds its final logo frame");yield return Wait(1);Check(menu.IntroHolding,"Logo still visible one second after video ends");yield return Wait(1);Check(!VoyageMainMenu.IntroVisible,"Menu appears after logo hold");
  menu.GetComponentsInChildren<Button>(true).First(b=>b.name=="Settings").onClick.Invoke();var sliders=menu.GetComponentsInChildren<Slider>();Check(sliders.Length==2,"Settings has master and music controls");sliders[0].value=.4f;sliders[1].value=.5f;yield return Wait(.2f);Check(Mathf.Abs(AudioListener.volume-.4f)<.001f&&PlayerPrefs.GetFloat("Sound.Music")==.5f,"Audio controls affect listener and music preference");ScreenCapture.CaptureScreenshot("Tools/PolishUpdate/settings.png");yield return Wait(.15f);
  Stage(JourneyStage.ShipBattle);yield return SceneManager.LoadSceneAsync(StorySceneJourney.ShipPath);yield return Wait(.4f);yield return Talk();var ship=UnityEngine.Object.FindFirstObjectByType<ShipController>();var ui=UnityEngine.Object.FindFirstObjectByType<ShipUIManager>();var water=ship.GetComponent<ShipWaterPurification>();var spawner=UnityEngine.Object.FindFirstObjectByType<EnemySpawner>();Check(spawner.selectedEnemyPrefabs.Length>0&&spawner.selectedEnemyPrefabs.All(p=>!p.name.Contains("Shark")&&!p.name.Contains("Whale")&&!p.name.Contains("Orca")),"First attack uses only small fish");Check(UnityEngine.Object.FindObjectsByType<Enemy>(FindObjectsSortMode.None).All(e=>e.movementSpeedMultiplier==1.15f),"Spawned fish move 15% faster without editing shared stats");
  Check(Mathf.Abs(ship.transform.position.x-(VoyageHarbor.CoastX+13))<1,"Ship starts in western harbour");Check(Physics2D.OverlapPoint(new Vector2(VoyageHarbor.CoastX-20,200)),"Mainland remains solid far north of town, not an island");Check(VoyageHarbor.NearestWater(new Vector2(VoyageHarbor.CoastX-20,0)).x>VoyageHarbor.CoastX,"Enemy placement avoids land and docks");Check(water.NormalizedProgress<.01f,"New visit water starts at zero");Check(UnityEngine.Object.FindFirstObjectByType<InfiniteOcean>().pollution==.4f,"Small-fish visit has matching stage-one pollution");Check(GameObject.Find("Floating surface waste"),"Surface litter exists");Check(ship.GetComponent<ShipWeapons>().allTurrets.All(t=>t.GetComponentInChildren<SpriteRenderer>(true).sortingOrder>1000),"Cannons render above hull");
  var music=UnityEngine.Object.FindFirstObjectByType<VoyageMusic>();yield return Wait(1);Check(music.GetComponents<AudioSource>().Any(s=>s.isPlaying&&s.clip.name=="surface"),"Surface music actually plays");
  var pause=UnityEngine.Object.FindFirstObjectByType<VoyagePauseMenu>();var keyboard=InputSystem.AddDevice<Keyboard>("PolishCheckKeyboard");InputSystem.QueueStateEvent(keyboard,new KeyboardState(Key.Escape));yield return Wait(.2f);Check(VoyagePauseMenu.IsOpen&&Time.timeScale==0&&!ship.enabled,"Escape opens menu and freezes ship controls");InputSystem.QueueStateEvent(keyboard,new KeyboardState());yield return Wait(.1f);ScreenCapture.CaptureScreenshot("Tools/PolishUpdate/pause.png");yield return Wait(.15f);pause.Close();Check(Time.timeScale==1&&ship.enabled,"Resume restores exact gameplay state");
  typeof(PlayerHealth).GetProperty("IsInvulnerable").SetValue(ship.GetComponent<PlayerHealth>(),true);
  InputSystem.QueueStateEvent(keyboard,new KeyboardState(Key.D));yield return Wait(1.8f);
  InputSystem.QueueStateEvent(keyboard,new KeyboardState(Key.D,Key.LeftShift));yield return Wait(.15f);InputSystem.QueueStateEvent(keyboard,new KeyboardState());yield return Wait(1.1f);
  InputSystem.QueueStateEvent(keyboard,new KeyboardState(Key.Space));yield return Wait(.2f);InputSystem.QueueStateEvent(keyboard,new KeyboardState());yield return Wait(1.1f);
  Check(!GameObject.Find("First use controls"),"Movement, boost and loot instructions disappear after real first-use inputs; remaining="+(GameObject.Find("Control instructions")?GameObject.Find("Control instructions").GetComponent<Text>().text:"none"));InputSystem.RemoveDevice(keyboard);

  // The native level-up API is exercised on a test-only paused frame.
  Time.timeScale=0;typeof(ShipUIManager).GetMethod("ShowLevelUpScreen",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(ui,null);yield return Wait(.2f);ScreenCapture.CaptureScreenshot("Tools/PolishUpdate/level.png");yield return Wait(.2f);pause.Open();pause.Close();Check(Time.timeScale==0,"Pause over card selection preserves the card pause");ui.OnCardClicked(0);yield return Wait(.1f);
  var originalId=ship.GetInstanceID();ship.currentEnergy=0;yield return Wait(1);var retry=UnityEngine.Object.FindFirstObjectByType<ShipController>();Check(retry&&retry.GetInstanceID()!=originalId&&StorySceneJourney.Instance.Stage==JourneyStage.ShipBattle,"Energy depletion restarts this visit without advancing story");Check(retry.currentEnergy==retry.maxEnergy&&retry.GetComponent<ShipWaterPurification>().NormalizedProgress==0,"Retry initializes full energy and empty water before gameplay resumes");yield return Talk();originalId=retry.GetInstanceID();typeof(PlayerHealth).GetProperty("IsInvulnerable").SetValue(retry.GetComponent<PlayerHealth>(),false);retry.GetComponent<PlayerHealth>().TakeDamage(99999);yield return Wait(1);retry=UnityEngine.Object.FindFirstObjectByType<ShipController>();Check(retry&&retry.GetInstanceID()!=originalId&&StorySceneJourney.Instance.Stage==JourneyStage.ShipBattle,"Zero health restarts the same section");Check(retry.GetComponent<PlayerHealth>().CurrentHealth==retry.GetComponent<PlayerHealth>().MaxHealth,"Health is full at retry entry");yield return Talk();
  Stage(JourneyStage.SharkBattle);yield return SceneManager.LoadSceneAsync(StorySceneJourney.ShipPath);yield return Wait(.4f);yield return Talk();spawner=UnityEngine.Object.FindFirstObjectByType<EnemySpawner>();Check(spawner.selectedEnemyPrefabs.Any(p=>p.name.Contains("Shark"))&&spawner.selectedEnemyPrefabs.Any(p=>p.name.Contains("Fish"))&&!spawner.selectedEnemyPrefabs.Any(p=>p.name.Contains("Whale")||p.name.Contains("Orca")),"Second attack mixes small fish and sharks");Check(UnityEngine.Object.FindFirstObjectByType<InfiniteOcean>().pollution==.8f,"Second attack is dirtier");ScreenCapture.CaptureScreenshot("Tools/PolishUpdate/coast.png");yield return Wait(.15f);
  Stage(JourneyStage.WhaleBattle);yield return SceneManager.LoadSceneAsync(StorySceneJourney.ShipPath);yield return Wait(.4f);yield return Talk();spawner=UnityEngine.Object.FindFirstObjectByType<EnemySpawner>();Check(spawner.selectedEnemyPrefabs.Any(p=>p.name.Contains("Whale"))&&spawner.selectedEnemyPrefabs.Any(p=>p.name.Contains("Shark"))&&spawner.selectedEnemyPrefabs.Any(p=>p.name.Contains("Fish")),"Last attack includes whales with earlier fish");Check(UnityEngine.Object.FindFirstObjectByType<InfiniteOcean>().pollution==.92f,"Final attack is dirtiest");
  var vessel=UnityEngine.Object.FindFirstObjectByType<ShipController>();vessel.enabled=false;var vesselBody=vessel.GetComponent<Rigidbody2D>();vesselBody.position=new Vector2(VoyageHarbor.CoastX+6,80);vesselBody.linearVelocity=Vector2.left*15;yield return Wait(1);Check(vesselBody.position.x>VoyageHarbor.CoastX+1&&vesselBody.IsTouching(GameObject.Find("Mainland boundary").GetComponent<Collider2D>()),"Actual ship physics blocks entry onto the continuous mainland");
  Stage(JourneyStage.FirstUnderwater);yield return SceneManager.LoadSceneAsync(StorySceneJourney.UnderwaterPath);yield return Wait(.8f);var story=UnityEngine.Object.FindFirstObjectByType<UnderwaterDayStory>();story.ui.Clear();Check(story.interactDistance>=4.5f&&story.secondChapter.meetingRadius>=6&&story.thirdChapter.talkRadius>=7,"Conversation reaches are enlarged consistently");yield return Wait(.5f);Check(!music.GetComponents<AudioSource>().Any(s=>s.isPlaying),"Ordinary underwater chapter keeps only ambience, no music");
  var pilot=story.player;pilot.ControlsLocked=false;var rb=pilot.GetComponent<Rigidbody2D>();rb.position=new Vector2(story.Discovery.x+15,pilot.surfaceY-1);rb.linearVelocity=Vector2.up*pilot.speed;pilot.testInput=Vector2.up;pilot.testSprint=true;bool jumped=false;float maxY=rb.position.y;for(int i=0;i<100;i++){maxY=Mathf.Max(maxY,rb.position.y);if(pilot.Airborne)jumped=true;if(jumped&&!pilot.Airborne)break;yield return Wait(.02f);}Check(jumped&&maxY>pilot.surfaceY&&pilot.SplashCount>=2,"Boost toward surface launches a short jump with exit and landing splashes");pilot.testInput=Vector2.zero;pilot.testSprint=false;
  story.secondChapter.ResetChapter();typeof(UnderwaterSecondChapter).GetField("stage",BindingFlags.NonPublic|BindingFlags.Instance).SetValue(story.secondChapter,SecondChapterStage.LeaveForSharks);rb.position=new Vector2(story.secondChapter.departurePoint.x,-25);pilot.transform.position=rb.position;Physics2D.SyncTransforms();story.secondChapter.Tick();Check(story.secondChapter.Complete,"Shark departure accepts the vertical boundary far below the label");
  Check(errors==0,"No runtime errors during polish verification");Time.timeScale=1;yield return SceneManager.LoadSceneAsync("MainMenu");
 }
}
